package com.example

/**
 * Curated, 100% syllabus-aligned Flashcards for Health & Physical Education (සෞඛ්‍යය හා ශාරීරික).
 * Part 2: Categories 11 to 20 (20 distinct questions per category = 200 unique questions).
 */
object FlashcardBankHealthSetsPart2 {

  fun getHealthSet(s: Int, c: Int, grade: String = "10"): CardContentTuple? {
    if (grade.contains("11")) {
      return when (s) {
        11 -> grade11_getSet11(c)
        12 -> grade11_getSet12(c)
        13 -> grade11_getSet13(c)
        14 -> grade11_getSet14(c)
        15 -> grade11_getSet15(c)
        16 -> grade11_getSet16(c)
        17 -> grade11_getSet17(c)
        18 -> grade11_getSet18(c)
        19 -> grade11_getSet19(c)
        20 -> grade11_getSet20(c)
        else -> null
      }
    }
    return when (s) {
      11 -> getSet11(c)
      12 -> getSet12(c)
      13 -> getSet13(c)
      14 -> getSet14(c)
      15 -> getSet15(c)
      16 -> getSet16(c)
      17 -> getSet17(c)
      18 -> getSet18(c)
      19 -> getSet19(c)
      20 -> getSet20(c)
      else -> null
    }
  }

  // Set 11: ජිම්නාස්ටික් සහ රිද්මයානුකූල චලන (Gymnastics & Rhythmic Movements)
  private fun getSet11(c: Int): CardContentTuple = when (c) {
    1 -> CardContentTuple("ජිම්නාස්ටික් ක්‍රීඩාවේ මූලික කුසලතා කාණ්ඩ 3 මොනවාද?", "බිම් අභ්‍යාස (Floor exercises), සමබරතා අභ්‍යාස (Balancing), සහ උපකරණ ආශ්‍රිත අභ්‍යාස (Vault/Bars).", "විභාග උපදෙස: නම්‍යශීලී බව සහ ශරීර පාලනය මූලික වේ.", "සෞඛ්‍යය • කාණ්ඩය 11")
    2 -> CardContentTuple("බිම් අභ්‍යාසවල පෙරළීම් (Rolls) 2ක් නම් කරන්න.", "ඉදිරි පෙරළිය (Forward Roll) සහ පසුපස පෙරළිය (Backward Roll).", "විභාග උපදෙස: නිකට පපුවට තද කර කොඳු ඇට පෙළ වක්‍රව තබා ගත යුතුය.", "සෞඛ්‍යය • කාණ්ඩය 11")
    3 -> CardContentTuple("කරණම හෙවත් Cartwheel ක්‍රියාවලිය පැහැදිලි කරන්න.", "සිරුර පැත්තකට හරවා අත් දෙක සහ පාද දෙක අනුක්‍රමිකව බිම තබමින් සම්පූර්ණ අංශක 360 ක වෘත්තාකාර පැති කරණමක් ගැසීම.", "විභාග උපදෙස: පාද කෙළින් තබා ගැනීම අලංකාරයට හේතු වේ.", "සෞඛ්‍යය • කාණ්ඩය 11")
    4 -> CardContentTuple("හිසෙන් සිටගැනීම (Headstand) සඳහා සිරුර තැබිය යුතු ත්‍රිකෝණාකාර පදනම කුමක්ද?", "හිසේ මුදුන සහ දෑත් බිම තබා සමපාද ත්‍රිකෝණයක පිහිටුම නිර්මාණය කිරීම.", "විභාග උපදෙස: සමබරතාවය රඳවා ගැනීමට ත්‍රිකෝණාකාර පදනම අත්‍යවශ්‍ය වේ.", "සෞඛ්‍යය • කාණ්ඩය 11")
    5 -> CardContentTuple("අතින් සිටගැනීමේ (Handstand) මූලික ශිල්පීය රීතිය කුමක්ද?", "දෑත් උරහිස් පළලින් තබා වැලමිට නොනමා කෙළින් තබාගෙන උදර සහ පාද පේශි තද කර සිරුර සිරස්ව පවත්වා ගැනීම.", "විභාග උපදෙස: බිත්තියක ආධාරයෙන් මුලින් පුහුණු වේ.", "සෞඛ්‍යය • කාණ්ඩය 11")
    6 -> CardContentTuple("පිරමිඩ නිර්මාණයේදී (Pyramid Formations) සැලකිලිමත් විය යුතු ආරක්ෂක රීතියක් දක්වන්න.", "ශක්තිමත් සහ බරින් වැඩි සාමාජිකයින් පාදමේ (Base) සිටිය යුතු අතර සැහැල්ලු සාමාජිකයින් ඉහළට යා යුතුය.", "විභාග උපදෙස: එකිනෙකා අතර විශ්වාසය සහ සන්නිවේදනය වැදගත් වේ.", "සෞඛ්‍යය • කාණ්ඩය 11")
    7 -> CardContentTuple("රිද්මයානුකූල චලන (Rhythmic Movements) සංගීතයට අනුව කිරීමේ වාසිය කුමක්ද?", "ශරීරයේ සම්බන්ධීකරණය, කාල ගණනය (Timing), රිද්ම සංවේදනය සහ මානසික ප්‍රබෝධය ඉහළ නැංවීම.", "විභාග උපදෙස: සාමූහික විනය වර්ධනය කරයි.", "සෞඛ්‍යය • කාණ්ඩය 11")
    8 -> CardContentTuple("රිද්මයානුකූල ජිම්නාස්ටික් සඳහා භාවිත කරන කුඩා උපකරණ 3ක් නම් කරන්න.", "රිබන් පටිය (Ribbon), වළල්ල (Hoop), සහ පන්දුව (Ball) හෝ මුගුරු (Clubs).", "විභාග උපදෙස: කාන්තා ඉසව්වක් ලෙස ඔලිම්පික් උළෙලට ඇතුළත් වේ.", "සෞඛ්‍යය • කාණ්ඩය 11")
    9 -> CardContentTuple("සමබරතා බාල්කය (Balance Beam) මත කරන මූලික අභ්‍යාසයක් දක්වන්න.", "සමබරතාව පවත්වා ගනිමින් බාල්කය දිගේ ඇවිදීම, තනි පාදයෙන් සමබර වීම (Scale/Arabesque), සහ හැරීම් (Pivot turns).", "විභාග උපදෙස: බාල්කයේ පළල සෙ.මී. 10 කි.", "සෞඛ්‍යය • කාණ්ඩය 11")
    10 -> CardContentTuple("ජිම්නාස්ටික් පුහුණුවේදී ආරක්ෂක මෙට්ට (Spotting & Landing Mats) භාවිතයේ අරමුණ කුමක්ද?", "වැටීම්වලදී ඇතිවන කම්පනය උරාගෙන අස්ථි සහ සන්ධි ආබාධවලින් ක්‍රීඩකයා ආරක්ෂා කිරීම.", "විභාග උපදෙස: පුහුණුකරුගේ සහාය (Spotting) නව කුසලතාවලදී අනිවාර්යයි.", "සෞඛ්‍යය • කාණ්ඩය 11")
    11 -> CardContentTuple("ජිම්නාස්ටික් ක්‍රීඩාවෙන් සිරුරට ලැබෙන ප්‍රධානතම කායික ප්‍රතිලාභය කුමක්ද?", "අතිවිශිෂ්ට නම්‍යශීලී බවක් (Flexibility), මධ්‍ය පේශි ශක්තියක් (Core Strength), සහ අවකාශීය දැනුවත්භාවයක් ලැබීම.", "විභාග උපදෙස: සියලුම ක්‍රීඩාවලට මූලික පදනම සපයයි.", "සෞඛ්‍යය • කාණ්ඩය 11")
    12 -> CardContentTuple("පාලම (Bridge Pose) අභ්‍යාසය මඟින් ප්‍රධාන වශයෙන් දිග හැරෙන්නේ කුමන පේශිද?", "කොඳු ඇට පෙළ සහ උදර පේශි මෙන්ම උරහිස් සන්ධි.", "විභාග උපදෙස: කොන්දේ නම්‍යශීලී බව වැඩි කරයි.", "සෞඛ්‍යය • කාණ්ඩය 11")
